/* =====================================================================
   engine.docs.js  —  Engine.Docs   (blueprint §49)

   The documentation factory. Turns a scaffold spec (and, when present,
   the real `.sovereign/` runtime evidence) into the full operator-facing
   documentation set:

     /README.md              — what it is, how to run, project map
     /docs/API.md            — every HTTP route: auth, CRUD per entity,
                               query params, status codes, rate limits,
                               observability endpoints, GraphQL + WS
     /docs/DATABASE.md       — entities, columns, types, refs, indexes,
                               the real SQL migrations, JSON⇄Postgres note
     /docs/DEPLOYMENT.md     — env vars, build/migrate/start, Docker, and
                               one section per configured deploy target
     /docs/TROUBLESHOOTING.md— concrete symptom → cause → fix, tied to the
                               actual endpoints + behaviours this repo has

   Everything is derived — no placeholders. `generate(spec)` is pure and
   offline (used by Engine.Scaffold and the Ultra Mode loop). `analyze()`
   is the analysis-pass entry: it derives a spec from context, regenerates
   the set, folds in verification evidence, writes it into Engine.FS, and
   records a `documentation-index.json` in the Sovereign store.

   window.Engine.Docs
     generate(spec)  -> [{ path, content }]
     analyze()       -> { wrote:[...], enrichedWithEvidence:bool }
     load()          -> the written documentation-index.json or null
   ===================================================================== */
(function () {
  'use strict';
  var Engine = window.Engine || (window.Engine = {});
  var S = function () { return Engine.Sovereign; };
  var FS = function () { return Engine.FS; };

  function sread(name) {
    try { var v = S() && S().read(name); return v == null ? null : (typeof v === 'string' ? JSON.parse(v) : v); } catch (_) { return null; }
  }
  function fread(p) { try { return (FS() && FS().read(p)) || ''; } catch (_) { return ''; } }
  function has(p) { try { return !!(FS() && FS().isFile(p)); } catch (_) { return false; } }

  function norm(spec) {
    if (Engine.Scaffold && Engine.Scaffold.normalize) { try { return Engine.Scaffold.normalize(spec); } catch (_) {} }
    if (Engine.Schema && Engine.Schema.normalizeSpec) { try { return Engine.Schema.normalizeSpec(spec || {}); } catch (_) {} }
    return spec || { name: 'app', entities: [] };
  }

  var HIDDEN = { user: 1, session: 1, job: 1 };
  function resources(s) { return (s.entities || []).filter(function (e) { return !HIDDEN[e.name]; }); }
  function plural(name) { return /s$/.test(name) ? name : name + 's'; }
  function title(x) { return String(x || '').replace(/(^|[\s_-])([a-z])/g, function (_, a, b) { return a + b.toUpperCase(); }); }
  function fence(lang, body) { return '```' + (lang || '') + '\n' + body + '\n```\n'; }

  /* ---------- a small, honest example value per field type ---------- */
  function example(f) {
    switch (f.type) {
      case 'id': return '"' + (f.name === 'id' ? '01H…' : '01H…') + '"';
      case 'int': return '42';
      case 'float': return '9.99';
      case 'bool': return (f.def != null ? String(!!f.def) : 'false');
      case 'ref': return '"' + (f.ref || 'row') + '-id"';
      case 'json': return '{}';
      case 'date': case 'datetime': return '"2026-01-01T00:00:00.000Z"';
      case 'longtext': return '"…"';
      default: return '"' + title(f.name) + '"';
    }
  }
  function bodyExample(e, opts) {
    opts = opts || {};
    var fields = e.fields.filter(function (f) {
      if (f.type === 'id') return false;
      if (opts.writable && f.name === 'id') return false;
      return true;
    });
    var lines = fields.map(function (f) { return '  "' + f.name + '": ' + example(f); });
    return '{\n' + lines.join(',\n') + '\n}';
  }

  /* ================================================================= */
  /*  README.md                                                          */
  /* ================================================================= */
  function readme(s, ev) {
    var py = s.pyBackend || s.backend === 'python';
    var L = [];
    L.push('# ' + s.name + '\n');
    L.push('Generated by **CodeSovereign** — a complete, dependency-free ' +
      (py ? 'pure-standard-library Python' : 'Node') + ' full-stack application, verified end to end.\n');

    L.push('## What it is\n');
    L.push('- **API** `' + (py ? 'app/main.py' : 'server.js') + '` — REST' +
      (s.api === 'graphql' ? ' + GraphQL' : '') + (s.websocket ? ' + WebSocket' : '') +
      (s.auth ? ', session auth + RBAC' : '') + ', CRUD per entity, rate limiting, request tracing');
    L.push('- **Data layer** `' + (py ? 'app/db.py' : 'src/db.js') + '` — schema-enforced store' +
      (s.stack === 'node-pg' ? ' (JSON in dev, Postgres via `DATABASE_URL`)' : ' (swap for Postgres via `DATABASE_URL`)'));
    L.push('- **Migrations** `db/migrations/*.sql` — real SQL, `npm run migrate`');
    if (s.auth) L.push('- **Auth** `' + (py ? 'app/auth.py' : 'src/auth.js') + '` — scrypt hashing, opaque sessions, `requireAuth` / `requireRole`');
    if (s.jobs) L.push('- **Jobs** `src/worker.js` — a durable queue + worker + SSE event stream');
    if (s.microservices) L.push('- **Microservices** `gateway/` + `services/*` — the monolith split into a gateway and per-domain services (compose file included)');
    L.push('- **Frontend** `public/` — real `fetch`, loading / error / empty states, WCAG-AA markup');
    L.push('- **Observability** — `/healthz`, `/readyz`, `/metrics` (Prometheus, p50/p95/p99), JSON access logs, `x-trace-id` per request');
    L.push('');

    L.push('## Entities\n');
    resources(s).forEach(function (e) {
      L.push('- **' + e.name + '** — ' + e.fields.filter(function (f) { return f.type !== 'id'; })
        .map(function (f) { return '`' + f.name + '` ' + f.type + (f.ref ? '→' + f.ref : ''); }).join(', '));
    });
    L.push('');

    L.push('## Run\n');
    L.push(fence('bash', (py
      ? 'npm run migrate   # python -m app.db\nnpm test          # python -m unittest\nnpm run dev       # http://localhost:4319'
      : 'npm install\nnpm run migrate\nnpm test\nnpm run dev       # http://localhost:4319')));

    L.push('## Documentation\n');
    L.push('| File | Contents |');
    L.push('|---|---|');
    L.push('| [docs/API.md](docs/API.md) | Every HTTP route, params, status codes, examples |');
    L.push('| [docs/DATABASE.md](docs/DATABASE.md) | Schema, columns, indexes, migrations |');
    L.push('| [docs/DEPLOYMENT.md](docs/DEPLOYMENT.md) | Env vars, build/migrate/start, per-target guides |');
    L.push('| [docs/TROUBLESHOOTING.md](docs/TROUBLESHOOTING.md) | Symptom → cause → fix |');
    if (has('/docs/DATA_MODEL.md')) L.push('| [docs/DATA_MODEL.md](docs/DATA_MODEL.md) | Data-model analysis notes |');
    L.push('');

    if (ev && ev.present) {
      L.push('## Verification status\n');
      L.push('_As of the last `Engine.Sovereign.analyze()` run._\n');
      if (ev.dod) {
        L.push('- **Definition of Done:** ' + (ev.dod.pass ? '✅ all ' + ev.dod.total + ' criteria PASS' :
          '⚠️ ' + ev.dod.failing.length + ' of ' + ev.dod.total + ' failing — `' + ev.dod.failing.join('`, `') + '`'));
      }
      if (ev.exec) L.push('- **Execution:** ' + (ev.exec.ok ? '✅' : '⚠️') + ' ' + (ev.exec.summary || (ev.exec.ok ? 'build + tests ran' : 'see execution-evidence.json')));
      if (ev.perf) L.push('- **Performance:** p50 ' + ev.perf.p50 + 'ms · p95 ' + ev.perf.p95 + 'ms · p99 ' + ev.perf.p99 + 'ms · ' + ev.perf.errors + ' errors' + (ev.perf.leak ? ' · ⚠️ memory-leak signal' : ''));
      if (ev.cert) L.push('- **Certificate:** `' + ev.cert + '` in `.sovereign/`');
      L.push('');
    }
    return L.join('\n');
  }

  /* ================================================================= */
  /*  docs/API.md                                                        */
  /* ================================================================= */
  function apiDoc(s) {
    var L = [];
    L.push('# ' + s.name + ' — HTTP API\n');
    L.push('Base URL: `http://localhost:4319` (dev). All request/response bodies are JSON.\n');

    L.push('## Conventions\n');
    L.push('- IDs are opaque strings.');
    L.push('- Timestamps are ISO-8601 UTC.');
    L.push('- Errors: `{ "error": "<message>" }` with a 4xx/5xx status.');
    L.push('- Every response carries an **`x-trace-id`** header; send `traceparent` to propagate a trace.');
    L.push('- `/api/*` is rate limited to **120 requests / 60s per IP** (`429` on breach).');
    L.push('');

    if (s.auth) {
      L.push('## Authentication\n');
      L.push('Session-based. `login` / `register` return `{ token, user }`; send it as `Authorization: Bearer <token>` on writes.\n');
      L.push('| Method | Path | Body | 2xx | Notes |');
      L.push('|---|---|---|---|---|');
      L.push('| POST | `/api/auth/register` | `{ email, password }` | `201 { token, user }` | first user may be granted `admin` |');
      L.push('| POST | `/api/auth/login` | `{ email, password }` | `200 { token, user }` | `401` on bad credentials |');
      L.push('| POST | `/api/auth/logout` | – | `200 { ok }` | revokes the bearer session |');
      L.push('| GET | `/api/auth/me` | – | `200 { user }` | `{ user: null }` when anonymous |');
      L.push('');
      L.push('Writes (`POST`/`PUT`/`PATCH`/`DELETE`) on entities require a valid bearer token (`401` otherwise). Row ownership / roles are enforced in the service layer (`403`).\n');
    } else {
      L.push('## Authentication\n\nNone — every route is open. Put this behind a gateway or add auth before exposing it.\n');
    }

    L.push('## Entities\n');
    L.push('Each entity is a REST resource under `/api/<plural>`.\n');
    resources(s).forEach(function (e) {
      var p = '/api/' + plural(e.name);
      L.push('### ' + title(e.name) + '  `' + p + '`\n');
      L.push('| Method | Path | Purpose | Success | Errors |');
      L.push('|---|---|---|---|---|');
      L.push('| GET | `' + p + '` | list | `200 [ … ]` | – |');
      L.push('| POST | `' + p + '` | create | `201 { … }` | `400` validation' + (s.auth ? ', `401`' : '') + ' |');
      L.push('| GET | `' + p + '/:id` | read one | `200 { … }` | `404` |');
      L.push('| PUT / PATCH | `' + p + '/:id` | update | `200 { … }` | `400`, `404`' + (s.auth ? ', `401`' : '') + ' |');
      L.push('| DELETE | `' + p + '/:id` | delete | `200 { ok:true }` | `404`' + (s.auth ? ', `401`' : '') + ' |');
      L.push('');
      L.push('**List query params:** `?limit=<n>&offset=<n>` for paging; ' +
        'any field name as `?<field>=<value>` for an exact-match filter (e.g. `' + p + '?' +
        (e.fields.filter(function (f) { return f.type !== 'id'; })[0] || { name: 'field' }).name + '=…`).\n');
      L.push('**Create body**');
      L.push(fence('json', bodyExample(e, { writable: true })));
      var refs = e.fields.filter(function (f) { return f.type === 'ref'; });
      if (refs.length) L.push('Reference fields (' + refs.map(function (f) { return '`' + f.name + '`→' + f.ref; }).join(', ') + ') must point at an existing row.\n');
    });

    if (s.jobs) {
      L.push('## Background jobs\n');
      L.push('| Method | Path | Body | Success |');
      L.push('|---|---|---|---|');
      L.push('| POST | `/api/jobs` | `{ type, payload }` | `202 { id, status }` |');
      L.push('| GET | `/api/jobs/stats` | – | `200 { queued, running, done, failed }` |');
      L.push('| GET | `/api/events` | – | `200` Server-Sent Events stream of job transitions |');
      L.push('');
    }

    if (s.api === 'graphql') {
      L.push('## GraphQL\n');
      L.push('`POST /graphql` (also `GET /graphql?query=…`). One `Query` field per entity list + one `Mutation` per create. Schema is served by the executor in `src/graphql*.js`.\n');
      L.push(fence('graphql', 'query { ' + (resources(s)[0] ? plural(resources(s)[0].name) : 'items') + ' { id } }'));
    }

    if (s.websocket) {
      L.push('## WebSocket\n');
      L.push('`ws://localhost:4319/ws` (RFC 6455, no library). The server echoes a `{ type:"welcome" }` frame on connect and broadcasts entity-change events. See `src/realtime*.js`.\n');
    }

    L.push('## Observability endpoints\n');
    L.push('| Path | Returns |');
    L.push('|---|---|');
    L.push('| `GET /healthz` | `200 { ok:true, uptime_s }` — liveness |');
    L.push('| `GET /readyz` | `200 { ready:true }` or `503 { ready:false, error }` — data-layer reachability |');
    L.push('| `GET /metrics` | Prometheus text — `app_request_latency_ms{quantile}`, `app_requests_total`, `app_errors_total`, `app_crashes_total`, `app_memory_heap_used_bytes`, response classes, method breakdown, uptime, RSS |');
    L.push('| `GET /debug/traces` | last 25 request traces with per-span timings (returns `404` when `NODE_ENV=production` unless `DEBUG_ENDPOINTS=1`) |');
    L.push('');
    L.push('Crashes (`uncaughtException` / `unhandledRejection`) are written to `logs/crashes/<timestamp>.json` and counted in `app_crashes_total`.\n');
    return L.join('\n');
  }

  /* ================================================================= */
  /*  docs/DATABASE.md                                                   */
  /* ================================================================= */
  function dbDoc(s) {
    var L = [];
    L.push('# ' + s.name + ' — database\n');
    L.push('The data layer is schema-enforced. In development it is a JSON store under `.data/`; ' +
      'set `DATABASE_URL=postgres://…` to run the identical schema on Postgres 16. The SQL below is the source of truth.\n');

    L.push('## Tables\n');
    (s.entities || []).forEach(function (e) {
      L.push('### `' + e.table + '`  (' + e.name + ')\n');
      L.push('| Column | Type | Constraints |');
      L.push('|---|---|---|');
      e.fields.forEach(function (f) {
        var c = [];
        if (f.type === 'id') c.push('primary key');
        if (f.required) c.push('not null');
        if (f.def != null) c.push('default `' + JSON.stringify(f.def) + '`');
        if (f.max) c.push('max len ' + f.max);
        if (f.ref) c.push('→ `' + (s.entities.filter(function (x) { return x.name === f.ref; })[0] || { table: f.ref }).table + '`' + (f.onDelete ? ' on delete ' + f.onDelete : ''));
        L.push('| `' + f.name + '` | ' + f.type + ' | ' + (c.join(', ') || '–') + ' |');
      });
      L.push('');
      if ((e.indexes || []).length) {
        L.push('Indexes: ' + e.indexes.map(function (ix) {
          return '`' + (ix.unique ? 'UNIQUE ' : '') + '(' + ix.fields.join(', ') + ')`';
        }).join(', ') + '\n');
      }
    });

    L.push('## Migrations\n');
    var migs = [];
    try {
      migs = Object.keys(FS()._data || {}).filter(function (p) { return /\/db\/migrations\/.+\.sql$/.test(p); }).sort();
    } catch (_) {}
    if (!migs.length && Engine.Schema && Engine.Schema.migrationsSQL) {
      try { migs = Object.keys(Engine.Schema.migrationsSQL(s)); } catch (_) {}
    }
    if (migs.length) {
      L.push('Apply with `npm run migrate` (idempotent — `CREATE TABLE IF NOT EXISTS`). Files, in order:\n');
      migs.forEach(function (m) { L.push('- `' + m.replace(/^\//, '') + '`'); });
      L.push('');
      var first = fread(migs[0].charAt(0) === '/' ? migs[0] : '/' + migs[0]);
      if (first) { L.push('First migration:\n'); L.push(fence('sql', first.trim())); }
    } else {
      L.push('_No migration files in this repo._\n');
    }

    L.push('## Backups & reset\n');
    L.push('- **Dev:** delete `.data/` and re-run `npm run migrate` for a clean slate.');
    L.push('- **Postgres:** `pg_dump` / `pg_restore` as usual; migrations are forward-only, a `*.down.sql` is emitted alongside each up.');
    L.push('');
    return L.join('\n');
  }

  /* ================================================================= */
  /*  docs/DEPLOYMENT.md                                                 */
  /* ================================================================= */
  function deployDoc(s) {
    var L = [];
    var targets = (s.deployTargets && s.deployTargets.length ? s.deployTargets : ['docker', 'compose']);
    L.push('# ' + s.name + ' — deployment\n');
    L.push('This project has **no runtime dependencies**, so any host that runs ' +
      (s.pyBackend ? 'Python 3.11+' : 'Node 20+') + ' can serve it. It **never deploys itself** — every target below generates artifacts you apply with your own credentials.\n');

    L.push('## Environment\n');
    L.push('| Variable | Default | Purpose |');
    L.push('|---|---|---|');
    L.push('| `PORT` | `4319` | listen port (`--port=` also works) |');
    L.push('| `DATABASE_URL` | – | `postgres://…` to use Postgres instead of the JSON store |');
    if (s.auth) L.push('| `SESSION_TTL_MS` | `604800000` | session lifetime |');
    L.push('| `NODE_ENV` | – | set to `production` to hide `/debug/traces` |');
    L.push('| `DEBUG_ENDPOINTS` | – | set to `1` to re-enable `/debug/traces` in production |');
    L.push('| `LOG_SILENT` | – | set to `1` to suppress the JSON access log |');
    L.push('');

    L.push('## Build, migrate, start\n');
    L.push(fence('bash', (s.pyBackend
      ? 'npm run migrate     # python -m app.db\nnpm run dev         # python -m app.main'
      : 'npm ci --omit=dev\nnpm run build       # if a build step is defined\nnpm run migrate\nnode server.js --port=$PORT')));

    L.push('## Health checks\n');
    L.push('Point your load balancer / orchestrator liveness at `GET /healthz` and readiness at `GET /readyz` (returns `503` until the data layer answers). Scrape `GET /metrics` with Prometheus.\n');

    var DEPLOY = Engine.Deploy;
    var meta = (DEPLOY && DEPLOY.TARGETS) || null;
    L.push('## Targets\n');
    targets.forEach(function (t) {
      var m = meta && meta[t];
      L.push('### ' + (m ? m.label : title(t)) + '\n');
      if (m) {
        L.push('- **Cost:** ' + m.cost);
        if (m.needs && m.needs.length) L.push('- **Needs:** ' + m.needs.join(', '));
        L.push('');
      }
      if (t === 'docker') {
        L.push(fence('bash', 'docker build -t ' + s.name + ' .\ndocker run -p 4319:4319 -e DATABASE_URL=$DATABASE_URL ' + s.name));
      } else if (t === 'compose') {
        L.push('App + Postgres 16, one command:\n');
        L.push(fence('bash', 'docker compose -f docker-compose.prod.yml up -d'));
      } else if (t === 'kubernetes') {
        L.push(fence('bash', 'kubectl apply -f deploy/kubernetes/'));
        L.push('Manifests: namespace, configmap, secret, deployment (probes + resource limits), service, ingress, HPA, Postgres StatefulSet.\n');
      } else if (t === 'helm') {
        L.push(fence('bash', 'helm upgrade --install ' + s.name + ' deploy/helm/' + s.name));
      } else if (t === 'terraform') {
        L.push(fence('bash', 'cd deploy/terraform && terraform init && terraform apply'));
        L.push('Provisions a DigitalOcean droplet + managed Postgres and runs the deploy script. Needs `DIGITALOCEAN_TOKEN`.\n');
      } else if (t === 'vps') {
        L.push(fence('bash', 'bash deploy/vps.sh user@host example.com'));
        L.push('Installs a systemd unit + a Caddy reverse proxy with automatic TLS.\n');
      } else if (t === 'fly') {
        L.push(fence('bash', 'fly launch --copy-config --now'));
      } else if (t === 'render' || t === 'railway') {
        L.push('Connect the Git remote in the ' + title(t) + ' dashboard; `' + (t === 'render' ? 'render.yaml' : 'railway.json') + '` is already in the repo.\n');
      } else if (t === 'static') {
        L.push('Front-end only: `npm run build` produces `dist/`, upload it to any static host. The API must be hosted separately.\n');
      }
      if (m && DEPLOY && DEPLOY.apply) L.push('_Run `Engine.Deploy.apply(\'' + t + '\')` to (re)generate the artifacts + a runnable `deploy/' + t + '.sh`._\n');
    });

    L.push('## Rollback\n');
    L.push('- **Container targets:** redeploy the previous image tag.');
    L.push('- **VPS:** `systemctl restart ' + s.name + '` after checking out the prior release; `db/migrations/*.down.sql` reverse a schema change.');
    L.push('');
    return L.join('\n');
  }

  /* ================================================================= */
  /*  docs/TROUBLESHOOTING.md                                            */
  /* ================================================================= */
  function troubleDoc(s, ev) {
    var L = [];
    L.push('# ' + s.name + ' — troubleshooting\n');
    L.push('Every symptom below maps to something this repo actually does.\n');

    function item(sym, cause, fix) {
      L.push('### ' + sym + '\n');
      L.push('**Cause.** ' + cause + '\n');
      L.push('**Fix.** ' + fix + '\n');
    }

    item('`EADDRINUSE` on start',
      'Port `4319` (or `$PORT`) is already held — often a previous run that did not exit.',
      'Start on another port: `node server.js --port=4400`. Or free it: `npx kill-port 4319` (or `lsof -ti:4319 | xargs kill`).');

    item('`GET /readyz` returns `503`',
      'The data layer is unreachable. With `DATABASE_URL` set, Postgres is down or the URL is wrong; without it, `.data/` is not writable.',
      'Check `DATABASE_URL` and that Postgres accepts connections; run `npm run migrate`; make sure the process can write `.data/`.');

    item('`npm run migrate` fails',
      'The migration SQL could not be applied — usually a pre-existing table with a different shape, or no DB permission.',
      'On a dev machine, delete `.data/` and retry. On Postgres, apply `db/migrations/*.down.sql` for the offending version, then re-run `migrate`.');

    if (s.auth) {
      item('Every write returns `401`',
        'No valid bearer token. Writes require `Authorization: Bearer <token>` from `POST /api/auth/login`.',
        'Log in, capture `token`, send it as the `Authorization` header. Tokens expire after `SESSION_TTL_MS`.');
      item('A write returns `403` for a logged-in user',
        'Row-ownership / role check in the service layer — the user does not own the row or lacks the role.',
        'Use the owning account, or grant the role. The first registered user is typically `admin`.');
    }

    item('`429 rate limit exceeded`',
      'More than 120 requests in 60s from one IP hit `/api/*` (fixed-window limiter in `server.js`).',
      'Back off and retry after the window. Raise the limit in `rateLimit()` if the caller is trusted, or put a real gateway in front.');

    item('`POST` create returns `400`',
      'Schema validation rejected the body — a required field missing, a bad type, or a `ref` that points at no row.',
      'Compare the body with `docs/API.md` → the entity’s create example. Reference fields must contain an existing id.');

    item('Response is slow / `p95` high in `/metrics`',
      'The JSON store rewrites a whole table file per write; under load that dominates. `test/perf.test.js` asserts `p95 < 3000ms`.',
      'Move to Postgres with `DATABASE_URL`. Inspect `GET /debug/traces` for the slow span. Run `node --expose-gc test/perf.test.js` locally to reproduce.');

    item('`app_crashes_total` is climbing',
      'An `uncaughtException` or `unhandledRejection` fired. Each one is written to `logs/crashes/<timestamp>.json` with the stack.',
      'Read the newest file in `logs/crashes/`, fix the throwing path, add a test. The process stays up (the handler logs and continues).');

    item('Memory grows over a long run',
      '`test/perf.test.js` does a least-squares fit on `heapUsed`; a sustained slope + >8MB growth is flagged as `memory-leak` by `Engine.PerfCheck`.',
      'Run the perf test with `--expose-gc`, capture a heap snapshot before/after, look for retained closures or an unbounded array/Map. The trace ring buffer and rate-limit map are already bounded.');

    item('`GET /debug/traces` returns `404` in production',
      'By design — it is disabled when `NODE_ENV=production`.',
      'Set `DEBUG_ENDPOINTS=1` temporarily, or read the `trace` id from the JSON access log and correlate with your log store.');

    if (s.api === 'graphql') item('GraphQL query returns `errors`',
      'The executor validates against the generated schema — an unknown field or wrong argument type.',
      'Introspect with `{ __schema { types { name } } }`; match field names to the entities in `docs/DATABASE.md`.');

    if (s.websocket) item('WebSocket closes immediately',
      'The upgrade handshake failed — wrong path (`/ws`) or a proxy stripping the `Upgrade` header.',
      'Connect to `ws://host:4319/ws`; if behind nginx/Caddy, forward `Upgrade` + `Connection` headers.');

    if (s.microservices) item('Gateway returns `502` for one resource',
      'The per-domain service for that entity is not running or not reachable on its port.',
      'Start every service (`docker compose up`), or run the monolith fallback: `npm run start:monolith`.');

    item('`npm test` fails only in CI',
      'CI runners are slower — usually the perf `p95` assertion or a timing-sensitive integration test.',
      '`CS_PERF_N` lowers the perf load; the threshold is already generous (3000ms). Check the failing assertion name in the run output.');

    L.push('## Getting more detail\n');
    L.push('- **Per-request:** grab `x-trace-id` from the response, find it in the JSON access log, then in `GET /debug/traces` for span timings.');
    L.push('- **System:** `GET /metrics` for latency quantiles, error/crash counters, heap + RSS.');
    L.push('- **Verification:** re-run `Engine.Sovereign.analyze()` and read `.sovereign/definition-of-done.json` + `release-certificate.md`.');
    L.push('');
    return L.join('\n');
  }

  /* ================================================================= */
  /*  public API                                                         */
  /* ================================================================= */
  function generate(spec, ev) {
    var s = norm(spec);
    var out = [
      { path: '/README.md', content: readme(s, ev) },
      { path: '/docs/API.md', content: apiDoc(s) },
      { path: '/docs/DATABASE.md', content: dbDoc(s) },
      { path: '/docs/DEPLOYMENT.md', content: deployDoc(s) },
      { path: '/docs/TROUBLESHOOTING.md', content: troubleDoc(s, ev) }
    ];
    return out;
  }

  function evidence() {
    var dod = sread('definition-of-done.json');
    var exec = sread('execution-evidence.json');
    var perf = sread('perf-findings.json');
    var certRaw = null;
    try { certRaw = S() && S().read('release-certificate.md'); } catch (_) {}
    if (!dod && !exec && !perf) return { present: false };
    var ev = { present: true };
    if (dod) ev.dod = {
      pass: dod.pass === true || dod.passed === true || (dod.status === 'PASS'),
      total: (dod.criteria ? Object.keys(dod.criteria).length : (dod.total || 0)),
      failing: dod.failing || (dod.criteria ? Object.keys(dod.criteria).filter(function (k) { return !dod.criteria[k]; }) : [])
    };
    if (exec) ev.exec = { ok: exec.ok === true || exec.pass === true, summary: exec.summary || null };
    if (perf && perf.present) ev.perf = { p50: perf.p50, p95: perf.p95, p99: perf.p99, errors: perf.errors || 0, leak: !!perf.leak };
    if (certRaw) ev.cert = 'release-certificate.md';
    return ev;
  }

  function analyze() {
    var wrote = [];
    if (!S() || !FS()) return { wrote: wrote, enrichedWithEvidence: false };
    // only (re)write docs when a product repo is actually present
    if (!has('/package.json') && !has('/server.js') && !has('/app/main.py')) {
      S().write('documentation-index.json', { generatedAt: Date.now(), present: false, note: 'no product repo in the workspace — documentation factory idle' });
      return { wrote: wrote, enrichedWithEvidence: false };
    }
    var spec;
    try { spec = Engine.Scaffold && Engine.Scaffold.specFromContext ? Engine.Scaffold.specFromContext() : null; } catch (_) { spec = null; }
    if (!spec) spec = norm({ name: 'app', entities: [] });
    var ev = evidence();
    var docs = generate(spec, ev.present ? ev : null);
    docs.forEach(function (d) {
      // never clobber a hand-written README that isn't ours
      if (d.path === '/README.md' && has('/README.md') && !/Generated by \*\*CodeSovereign\*\*/.test(fread('/README.md'))) return;
      try { FS().write(d.path, d.content); wrote.push(d.path); } catch (_) {}
    });
    // §6 — the contract as /project-docs/*.md (Ultra Mode / direct-contract path)
    try {
      projectSpec().forEach(function (d) { try { FS().write(d.path, d.content); wrote.push(d.path); } catch (_) {} });
    } catch (_) {}
    var index = {
      generatedAt: Date.now(), present: true,
      files: wrote,
      entities: resources(norm(spec)).map(function (e) { return e.name; }),
      enrichedWithEvidence: ev.present,
      evidence: ev.present ? ev : null
    };
    S().write('documentation-index.json', index);
    S().write('documentation-report.md',
      '# Documentation factory\n\n_Generated ' + new Date(index.generatedAt).toISOString() + '_\n\n' +
      'Wrote ' + wrote.length + ' file(s): ' + wrote.map(function (p) { return '`' + p.replace(/^\//, '') + '`'; }).join(', ') + '.\n\n' +
      (ev.present ? 'Verification evidence folded into README.md.\n' : 'No `.sovereign/` verification evidence yet — run a full analyze/Ultra Mode pass to enrich.\n'));
    return { wrote: wrote, enrichedWithEvidence: ev.present };
  }

  // §6 — the contract IS the driven product specification. Materialise it as
  // /project-docs/*.md so the older writeProjectDocs() markdown surface is fed
  // by the Ultra Mode / direct-contract path, not only the Universal composer.
  function projectSpec() {
    var c = Engine.Contract && Engine.Contract.load && Engine.Contract.load();
    if (!c || !Array.isArray(c.requirements)) return [];
    var st = c.supportedStack || {};
    var ents = (c.entities || []);
    var reqRow = function (r) { return '- **' + r.id + '** (' + (r.priority || 'optional') + (r.source === 'llm' ? ', implied' : '') + ') — ' + r.statement; };
    var mand = (c.scope && c.scope.mandatory) || [];
    var verif = (Engine.Requirements && Engine.Requirements.loadVerification && Engine.Requirements.loadVerification()) || null;
    var out = [];
    out.push({ path: '/project-docs/product-spec.md',
      content: '# ' + ((c.product && c.product.name) || 'Product') + ' — product specification\n\n' +
        '_Derived from the machine-readable contract (`.sovereign/product-contract.json`)._\n\n' +
        '## Objective\n\n' + ((c.product && c.product.objective) || (c.product && c.product.prompt) || '') + '\n\n' +
        '## Verdict\n\n`' + c.verdict + '`' + (c.target && c.target !== 'web' ? ' · target: `' + c.target + '`' : '') + '\n\n' +
        '## Scope\n\n' + mand.length + ' mandatory requirement(s), ' + (c.requirements.length - mand.length) + ' optional. ' +
        (c.unsupported && c.unsupported.length ? c.unsupported.length + ' item(s) outside the supported stack. ' : '') +
        (c.unsafe && c.unsafe.length ? '**Refused (unsafe):** ' + c.unsafe.map(function (u) { return u.reason; }).join('; ') + '.' : '') + '\n' });
    out.push({ path: '/project-docs/requirements.md',
      content: '# Requirements\n\n' +
        (verif ? '_' + verif.summary + '_\n\n' : '') +
        '## Requested\n\n' + c.requirements.filter(function (r) { return r.source !== 'llm'; }).map(reqRow).join('\n') + '\n\n' +
        '## Implied (added by analysis)\n\n' + (c.requirements.filter(function (r) { return r.source === 'llm'; }).map(reqRow).join('\n') || '_none_') + '\n\n' +
        (verif && verif.missing && verif.missing.length
          ? '## Missing (domain-implied, not yet in the build)\n\n' + verif.missing.map(function (m) { return '- ' + m.requirement + ' — ' + m.why; }).join('\n') + '\n\n' : '') +
        '## Acceptance criteria\n\n' + (c.acceptanceCriteria || []).map(function (a) { return '- **' + a.id + '** → ' + a.requirementId + ': ' + (a.then || a.when || ''); }).join('\n') + '\n' });
    out.push({ path: '/project-docs/architecture.md',
      content: '# Architecture\n\n' +
        '## Stack\n\n' +
        '- Frontend: ' + (st.frontend || 'vanilla') + '\n- Backend: ' + (st.backend || 'node') + '\n- Database: ' + (st.database || 'json') +
        '\n- API: ' + (st.api || 'rest') + (st.websocket ? ' + WebSocket/SSE' : '') + '\n- Architecture: ' + (st.architecture || 'monolith') +
        '\n- Auth: ' + (st.auth ? 'session' + (st.rbac ? ' + RBAC' : '') + (c.authMethods && (c.authMethods.oauth || c.authMethods.mfa || c.authMethods.passkeys) ? ' + ' + ['oauth', 'mfa', 'passkeys'].filter(function (k) { return c.authMethods[k]; }).join('/') : '') : 'none') +
        '\n- Background jobs: ' + (st.jobs ? 'durable queue + worker' : 'none') + '\n- Deploy: ' + ((c.deployment && c.deployment.targets) || []).join(', ') + '\n\n' +
        '## Entities\n\n' + ents.map(function (e) { return '- **' + e.name + '**' + (e.fields ? ' (' + e.fields.map(function (f) { return f.name; }).join(', ') + ')' : ''); }).join('\n') + '\n\n' +
        '## Layering rules\n\n- the browser layer never imports server code or a DB driver — all data access is via the API\n- password/token crypto lives on the server only\n- services use the data layer (`src/db`), never their own DB connection\n- the data layer never imports the service layer (no inverted dependency)\n\nEnforced by `Engine.ArchRules` → `.sovereign/architecture-findings.json`.\n' });
    out.push({ path: '/project-docs/api.md',
      content: '# API\n\n' + ((c.apiRequirements || []).length
        ? (c.apiRequirements || []).map(function (a) { return '- `' + a.method + ' ' + a.path + '`' + (a.auth ? ' — auth required' : '') + ' (' + a.requirementId + ')'; }).join('\n')
        : '_No explicit API routes in the contract; per-entity CRUD is generated for each entity._') + '\n' });
    out.push({ path: '/project-docs/constraints.md',
      content: '# Constraints & assumptions\n\n' +
        '## Assumptions\n\n' + (c.assumptions || []).map(function (a) { return '- **' + a.about + ':** ' + a.decision + ' — _' + a.rationale + '_'; }).join('\n') + '\n\n' +
        '## Security requirements\n\n' + (c.security || []).map(function (s) { return '- ' + s.statement; }).join('\n') + '\n\n' +
        (c.blockingQuestions && c.blockingQuestions.length ? '## Open questions\n\n' + c.blockingQuestions.map(function (q) { return '- ' + (q.question || q); }).join('\n') + '\n' : '') });
    return out;
  }

  function load() { return sread('documentation-index.json'); }

  Engine.Docs = { generate: generate, analyze: analyze, load: load, projectSpec: projectSpec, _evidence: evidence };
  console.info('[Docs] documentation factory ready — Engine.Docs');
})();
